def find_Max_Len_Even(str):
    """Write a python function to find the first maximum length of even word.

    Return the first word whose length is even and maximal among
    even-length words, or an empty string if there is no such word.
    """
    max_word = ""
    for word in str.split():
        if len(word) % 2 == 0 and len(word) > len(max_word):
            max_word = word
    return max_word
